def validate_custom(cmd: str):
    c1 = cmd.count("{file_name}"); c2 = cmd.count("{line_number}")
    if c1 != 1:
        eprint(f"Error: Incorrect editor command: '{cmd}'")
        eprint(""); eprint("Caused by:"); eprint("    Expected one occurrence of '{file_name}'.")
        sys.exit(1)
    if c2 != 1:
        eprint(f"Error: Incorrect editor command: '{cmd}'")
        eprint(""); eprint("Caused by:"); eprint("    Expected one occurrence of '{line_number}'.")
        sys.exit(1)

@dataclass
class Match:
    file: str
    line_no: int
    line: str
    start: int = 0
    end: int = 0


def is_hidden_path(path: str, root: str = "") -> bool:
    parts = path.split(os.sep)
    return any(p.startswith('.') and p not in ('.','..') for p in parts if p)


def type_matches(path: str, typ: str) -> bool:
    pats = TYPE_PATTERNS.get(typ, [])
    base = os.path.basename(path)
    rel = path.replace(os.sep, '/')
    for p in pats:
        # Support the glob vocabulary used in rg's type list well enough.
        if fnmatch.fnmatch(base, p) or fnmatch.fnmatch(rel, p):
            return True
    return False


def included_by_filters(path: str, opts: Opts, rel: str) -> bool:
    if opts.types and not any(type_matches(path, t) for t in opts.types):
        return False
    if opts.type_not and any(type_matches(path, t) for t in opts.type_not):
        return False
    if opts.globs:
        ok = False
        base = os.path.basename(path)
        for g in opts.globs:
            neg = g.startswith('!')
            gg = g[1:] if neg else g
            matched = fnmatch.fnmatch(rel, gg) or fnmatch.fnmatch(base, gg) or fnmatch.fnmatch(path, gg)
            if matched and neg: return False
            if matched: ok = True
        if not ok: return False
    return True


def iter_files(paths: List[str], opts: Opts):
    for p in paths:
        if os.path.isfile(p):
            if opts.hidden or not is_hidden_path(os.path.basename(p)):
                if included_by_filters(p, opts, os.path.basename(p)):
                    yield p
        elif os.path.isdir(p):
            root_abs = os.path.abspath(p)
            for root, dirs, files in os.walk(p, followlinks=opts.follow):
                if not opts.hidden:
                    dirs[:] = [d for d in dirs if not d.startswith('.')]
                    files = [f for f in files if not f.startswith('.')]
                dirs.sort(); files.sort()
                for f in files:
                    full = os.path.join(root, f)
                    rel = os.path.relpath(full, p).replace(os.sep, '/')
                    if included_by_filters(full, opts, rel):
                        yield full
        else:
            # The observed non-tty path errors are masked by terminal setup; in tty
            # mode we silently ignore to keep the UI usable.
            continue


def build_regex(opts: Opts):
    pat = opts.pattern or ""
    if opts.fixed:
        pat = re.escape(pat)
    if opts.word:
        pat = r"\b(?:" + pat + r")\b"
    flags = re.MULTILINE
    if opts.multiline: flags |= re.DOTALL
    if opts.ignore_case or (opts.smart_case and (opts.pattern or '').lower() == (opts.pattern or '')):
        flags |= re.IGNORECASE
    return re.compile(pat, flags)


def search(opts: Opts) -> List[Match]:
    rgx = build_regex(opts)
    matches: List[Match] = []
    for path in iter_files(opts.paths, opts):
        try:
            with open(path, 'r', encoding='utf-8', errors='replace') as f:
                if opts.multiline:
                    text = f.read()
                    line_starts = [0]
                    for m in re.finditer('\n', text): line_starts.append(m.end())
                    for m in rgx.finditer(text):
                        ln = text.count('\n', 0, m.start()) + 1
                        start_line = text.rfind('\n', 0, m.start()) + 1
                        end_line = text.find('\n', m.start())
                        if end_line < 0: end_line = len(text)
                        line = text[start_line:end_line]
                        matches.append(Match(path, ln, line.rstrip('\n\r'), max(0, m.start()-start_line), max(0, min(m.end(), end_line)-start_line)))
                else:
                    for no, line in enumerate(f, 1):
                        stripped = line.rstrip('\n\r')
                        for m in rgx.finditer(stripped):
                            matches.append(Match(path, no, stripped, m.start(), m.end()))
                            break
        except (OSError, UnicodeError):
            continue
    key = opts.sort or opts.sortr
    rev = opts.sortr is not None
    if key:
        def statval(m: Match):
            try: st=os.stat(m.file)
            except OSError: return 0
            return {"modified": st.st_mtime, "created": st.st_ctime, "accessed": st.st_atime}.get(key, m.file)
        matches.sort(key=statval, reverse=rev)
    return matches


def sgr(s: str, code: str) -> str:
    return f"\x1b[{code}m{s}\x1b[39m"


def render(matches: List[Match], selected: int, finished: bool, opts: Opts):
    cols, rows = shutil.get_terminal_size((120, 30))
    rows = max(rows, 5); cols = max(cols, 20)
    out = []
    out.append("\x1b[?25l")
    out.append("\x1b[1;1H")
    top = "╭" + "─"*(cols-2) + "╮"
    bot = "╰" + "─"*(cols-2) + "╯"
    out.append(top[:cols])
    for r in range(2, rows):
        out.append(f"\x1b[{r};1H│\x1b[{r};{cols}H│")
    out.append(f"\x1b[{rows-1};1H" + bot[:cols])
    max_lines = rows - 3
    r = 2; last_file = None
    start_index = 0
    # keep selected visible in a simple flattened display
    display_items: List[Tuple[str, Optional[Match]]] = []
    for m in matches:
        if m.file != last_file:
            display_items.append((m.file, None)); last_file = m.file
        display_items.append(("", m))
    # map selected match to display row
    sel_display = 0; count = -1
    for idx, (_, m) in enumerate(display_items):
        if m is not None:
            count += 1
            if count == selected: sel_display = idx; break
    if sel_display >= max_lines:
        start_index = sel_display - max_lines + 1
    item_count = -1
    for idx, (fname, m) in enumerate(display_items[start_index:start_index+max_lines], start=start_index):
        if m is None:
            txt = fname
            if len(txt) > cols-4: txt = txt[:cols-5] + "…"
            out.append(f"\x1b[{r};2H\x1b[38;5;13m" + txt + "\x1b[39m")
        else:
            item_count += 1
            # actual match index by counting before idx
            actual = sum(1 for _, mm in display_items[:idx+1] if mm is not None) - 1
            prefix = f"{m.line_no:>2}: " if m.line_no < 100 else f"{m.line_no}: "
            line = m.line.replace('\t', '    ')
            txt_plain = prefix + line
            if len(txt_plain) > cols-4: line = line[:max(0, cols-len(prefix)-5)] + "…"
            before = line[:m.start]
            mid = line[m.start:m.end] if m.end > m.start else ""
            after = line[m.end:]
            bg = "\x1b[48;2;58;58;58m" if actual == selected else ""
            nobg = "\x1b[49m" if actual == selected else ""
            rendered = f"\x1b[38;5;2m{prefix}\x1b[39m{before}\x1b[38;5;1m{mid}\x1b[39m{after}"
            out.append(f"\x1b[{r};2H" + bg + rendered + nobg)
        r += 1
    files = len(set(m.file for m in matches))
    if finished:
        msg = f"  \x1b[1m\x1b[38;5;0mFINISHED\x1b[22m\x1b[39m  Found {len(matches)} matches in {files} files."
        out.append(f"\x1b[{rows};1H\x1b[48;5;2m{msg}\x1b[49m")
        if matches:
            out.append(f"\x1b[{rows};{max(1, cols-4)}H{selected+1}/{len(matches)}")
    else:
        out.append(f"\x1b[{rows};1H\x1b[48;2;255;165;0m  \x1b[1m\x1b[38;5;0mSEARCHING\x1b[22m\x1b[39m \x1b[49m")
    sys.stdout.write(''.join(out)); sys.stdout.flush()


def leave_alt():
    sys.stdout.write("\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1002l\x1b[?1000l\x1b[39m\x1b[49m\x1b[0m\x1b[?25l\x1b[?1049l\x1b[?25h")
    sys.stdout.flush()


def run_editor(match: Match, opts: Opts):
    leave_alt()
    cmd = opts.custom_command
    if cmd:
        cmd = cmd.replace("{file_name}", match.file).replace("{line_number}", str(match.line_no))
        subprocess.call(cmd, shell=True)
        return
    ed = opts.editor or os.environ.get("IGREP_EDITOR") or os.environ.get("VISUAL") or os.environ.get("EDITOR")
    if not ed:
        ed = "vim"
    base = os.path.basename(ed)
    if base in ("vim","nvim","neovim","hx","helix","less"):
        args = [ed, f"+{match.line_no}", match.file]
    elif base in ("code","vscode","code-insiders","subl","sublime-text"):
        args = [ed, "-g", f"{match.file}:{match.line_no}"]
    elif base == "nano":
        args = [ed, f"+{match.line_no}", match.file]
    else:
        args = shlex.split(ed) + [match.file]
    try:
        subprocess.call(args)
    except FileNotFoundError:
        eprint(f"Error: No such file or directory (os error 2)")


def interactive(opts: Opts):
    # Match the observed behavior in non-terminal contexts.
    if not (sys.stdin.isatty() and sys.stdout.isatty()):
        eprint("Error: Resource temporarily unavailable (os error 11)")
        return 1
    # Compile/search before switching screen. Let Python regex errors look like errors;
    # the observed tool may panic in a worker for invalid regexes.
    try:
        matches = search(opts)
    except re.error as ex:
        eprint(str(ex)); eprint("Error: Resource temporarily unavailable (os error 11)"); return 1
    old = termios.tcgetattr(sys.stdin)
    selected = 0
    try:
        tty.setcbreak(sys.stdin.fileno())
        sys.stdout.write("\x1b[?25l\x1b[?1000h\x1b[?1002h\x1b[?1003h\x1b[?1015h\x1b[?1006h\x1b[?1049h")
        sys.stdout.flush()
        render(matches, selected, True, opts)
        pending_g = False
