            out.append(f"\x1b[{rows};{max(1, cols-4)}H{selected+1}/{len(matches)}")
    else:
        out.append(f"\x1b[{rows};1H\x1b[48;2;255;165;0m  \x1b[1m\x1b[38;5;0mSEARCHING\x1b[22m\x1b[39m \x1b[49m")
    sys.stdout.write(''.join(out)); sys.stdout.flush()


def leave_alt():
    sys.stdout.write("\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1002l\x1b[?1000l\x1b[39m\x1b[49m\x1b[0m\x1b[?25l\x1b[?1049l\x1b[?25h")
    sys.stdout.flush()


def run_editor(match: Match, opts: Opts):
    leave_alt()
    cmd = opts.custom_command
    if cmd:
        cmd = cmd.replace("{file_name}", match.file).replace("{line_number}", str(match.line_no))
        subprocess.call(cmd, shell=True)
        return
    ed = opts.editor or os.environ.get("IGREP_EDITOR") or os.environ.get("VISUAL") or os.environ.get("EDITOR")
    if not ed:
        ed = "vim"
    base = os.path.basename(ed)
    if base in ("vim","nvim","neovim","hx","helix","less"):
        args = [ed, f"+{match.line_no}", match.file]
    elif base in ("code","vscode","code-insiders","subl","sublime-text"):
        args = [ed, "-g", f"{match.file}:{match.line_no}"]
    elif base == "nano":
        args = [ed, f"+{match.line_no}", match.file]
    else:
        args = shlex.split(ed) + [match.file]
    try:
        subprocess.call(args)
    except FileNotFoundError:
        eprint(f"Error: No such file or directory (os error 2)")


def interactive(opts: Opts):
    # Match the observed behavior in non-terminal contexts.
    if not (sys.stdin.isatty() and sys.stdout.isatty()):
        eprint("Error: Resource temporarily unavailable (os error 11)")
        return 1
    # Compile/search before switching screen. Let Python regex errors look like errors;
    # the observed tool may panic in a worker for invalid regexes.
    try:
        matches = search(opts)
    except re.error as ex:
        eprint(str(ex)); eprint("Error: Resource temporarily unavailable (os error 11)"); return 1
    old = termios.tcgetattr(sys.stdin)
    selected = 0
    try:
        tty.setcbreak(sys.stdin.fileno())
        sys.stdout.write("\x1b[?25l\x1b[?1000h\x1b[?1002h\x1b[?1003h\x1b[?1015h\x1b[?1006h\x1b[?1049h")
        sys.stdout.flush()
        render(matches, selected, True, opts)
        pending_g = False
        while True:
            r,_,_ = select.select([sys.stdin], [], [], 0.25)
            if not r:
                continue
            ch = os.read(sys.stdin.fileno(), 16)
            if not ch:
                continue
            if ch in (b'q', b'\x1b', b'\x03'):
                break
            if ch in (b'j', b'\x1b[B', b'\n'):
                if matches: selected = min(len(matches)-1, selected+1); render(matches, selected, True, opts)
                pending_g = False; continue
            if ch in (b'k', b'\x1b[A'):
                if matches: selected = max(0, selected-1); render(matches, selected, True, opts)
                pending_g = False; continue
            if ch in (b'G', b'\x1b[F'):
                if matches: selected = len(matches)-1; render(matches, selected, True, opts)
                pending_g = False; continue
            if ch == b'g':
                if pending_g:
                    selected = 0; render(matches, selected, True, opts); pending_g=False
                else:
                    pending_g=True
                continue
            pending_g = False
            if ch in (b'\r',):
                if matches:
                    termios.tcsetattr(sys.stdin, termios.TCSADRAIN, old)
                    run_editor(matches[selected], opts)
                    return 0
            if ch in (b'd', b'\x7f'):
                if matches:
                    del matches[selected]
                    selected = min(selected, max(0, len(matches)-1)); render(matches, selected, True, opts)
        return 0
    finally:
        try: termios.tcsetattr(sys.stdin, termios.TCSADRAIN, old)
        except Exception: pass
        leave_alt()


def main(argv: List[str]) -> int:
    try:
        opts = parse_args(argv)
    except ClapError as ce:
        print_clap_error(ce); return 2
    if opts.type_list:
        try:
            sys.stdout.write(TYPE_LIST)
            if not TYPE_LIST.endswith('\n'): sys.stdout.write('\n')
            return 0
        except BrokenPipeError:
            # The original reports a broken pipe error; Python may receive SIGPIPE.
            try: eprint("Error: Broken pipe (os error 32)")
            except Exception: pass
            return 1
    return interactive(opts)

if __name__ == "__main__":
    signal.signal(signal.SIGPIPE, signal.SIG_DFL)
    sys.exit(main(sys.argv[1:]))
